import React from 'react';
import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <h1>Zoho SalesIQ Integration</h1>
        <p>Your Zoho SalesIQ widget is now active!</p>
      </header>
      <main className="App-main">
        <div className="content">
          <h2>Welcome to our website!</h2>
          <p>You can now chat with our support team using the Zoho SalesIQ widget.</p>
          <p>The chat widget should appear on the bottom right corner of this page.</p>
        </div>
      </main>
    </div>
  );
}

export default App;
